arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: <TOKEN>' -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name']=='documentUpdate':
        for a in f['args']:
            t=a['type']
            tn=t['name'] or (t.get('ofType') or {}).get('name') or t['kind']
            print(a['name'],'->',tn)
"

